   210→            if (header is null)
   211→            {
   212→                if (_logger.IsWarn) _logger.Warn("Could not find header for requested blockhash.");
   213→                preparedReceipts = null;
   214→            }
   215→            else
   216→            {
   217→                if (header.ReceiptsRoot == Keccak.EmptyTreeHash)
   218→                {
   219→                    preparedReceipts = receipts.Length == 0 ? receipts : null;
   220→                }
   221→                else
   222→                {
   223→                    // BlockInfo has no timestamp
   224→                    IReceiptSpec releaseSpec = _specProvider.GetReceiptSpec(blockInfo.BlockNumber);
   225→                    // TODO: Optimism use op root calculator
   226→                    preparedReceipts = ReceiptsRootCalculator.Instance.GetReceiptsRoot(receipts, releaseSpec, header.ReceiptsRoot) != header.ReceiptsRoot
   227→                        ? null
   228→                        : receipts;
   229→                }
   230→            }
   231→
   232→            return preparedReceipts is not null;
   233→        }
   234→
   235→        private int InsertReceipts(ReceiptsSyncBatch batch)
   236→        {
   237→            bool hasBreachedProtocol = false;
   238→            int validResponsesCount = 0;
   239→
   240→            BlockInfo?[] blockInfos = batch.Infos;
